/// 교감 상태 메시지 창 상태를 즉시 초기화한다.
void _resetInteractionStatusState({bool resetController = true}) {
  _interactionStatusGeneration++;
  _interactionStatusMessage = null;
  _isInteractionStatusOpen = false;
  _interactionStatusTransitionInProgress = false;
  _interactionStatusDismissRequested = false;
  _interactionStatusQueue.clear();
  _shownInteractionStatusEventKeys.clear();
  if (resetController) {
    _interactionStatusAnimationController.stop();
    _interactionStatusAnimationController.value = 0;
  }
}

bool _hasBlockingYardModalOpen() {
  return _isWithdrawConfirmOpen ||
      _isWithdrawFinalConfirmOpen ||
      _isWithdrawErrorNoticeOpen ||
      _isNameInterlockNoticeOpen ||
      _isProfileSelectMissingNoticeOpen ||
      _isAccountLinkInviteNoticeOpen ||
      _isAccountLinkSuccessNoticeOpen ||
      _isMealRecognitionFailureNoticeOpen ||
      _isMealVerificationLimitNoticeOpen ||
      _isLinkedAccountAddressNoticeOpen ||
      _isDuplicatePetNameNoticeOpen ||
      _isMaturityCompleteNoticeOpen ||
      _isPokedexCompleteTicketNoticeOpen ||
      _isRemoteAccountLinkedLogoutNoticeOpen ||
      _isRandomTicketUseConfirmOpen;
}

String? _activePetDisplayNickname() {
  final name = _activePet?['nickname']?.toString().trim();
  if (name == null || name.isEmpty) return null;
  return name;
}

String _interactionPlaySuccessMessage() {
  final l10n = AppLocalizations.of(context);
  final name = _activePetDisplayNickname();
  if (name == null) return l10n.interactionPlaySuccessFallback;
  return l10n.interactionPlaySuccess(name);
}

String _interactionPettingSuccessMessage() {
  final l10n = AppLocalizations.of(context);
  final name = _activePetDisplayNickname();
  if (name == null) return l10n.interactionPettingSuccessFallback;
  return l10n.interactionPettingSuccess(name);
}

void _enqueueInteractionStatusMessage(String message) {
  if (_interactionStatusQueue.isEmpty ||
      _interactionStatusQueue.last != message) {
    _interactionStatusQueue.add(message);
  }
}

/// 중요한 modal 이 열릴 때 현재 교감 메시지를 queue 앞으로 되돌린다.
void _stashInteractionStatusForBlockingModal() {
  if (!_isInteractionStatusOpen && !_interactionStatusTransitionInProgress) {
    return;
  }
  final current = _interactionStatusMessage?.trim();
  if (current != null && current.isNotEmpty) {
    if (_interactionStatusQueue.isEmpty ||
        _interactionStatusQueue.first != current) {
      _interactionStatusQueue.insert(0, current);
    }
  }
  _interactionStatusGeneration++;
  _interactionStatusMessage = null;
  _isInteractionStatusOpen = false;
  _interactionStatusTransitionInProgress = false;
  _interactionStatusDismissRequested = false;
  _interactionStatusAnimationController.stop();
  _interactionStatusAnimationController.value = 0;
}

Future<void> _presentNextInteractionStatusIfIdle() async {
  if (!mounted) return;
  if (_hasBlockingYardModalOpen()) return;
  if (_isInteractionStatusOpen || _interactionStatusTransitionInProgress) {
    return;
  }
  if (_interactionStatusQueue.isEmpty) return;
  final next = _interactionStatusQueue.removeAt(0);
  await _showInteractionStatusMessage(next);
}

Future<void> _showInteractionStatusMessage(
  String rawMessage, {
  String? eventKey,
}) async {
  final message = rawMessage.trim();
  if (message.isEmpty) return;

  if (eventKey != null) {
    if (_shownInteractionStatusEventKeys.contains(eventKey)) return;
    _shownInteractionStatusEventKeys.add(eventKey);
  }

  if (_hasBlockingYardModalOpen() ||
      _isInteractionStatusOpen ||
      _interactionStatusTransitionInProgress) {
    _enqueueInteractionStatusMessage(message);
    return;
  }

  final generation = ++_interactionStatusGeneration;
  _interactionStatusDismissRequested = false;

  _safeSetState(() {
    _interactionStatusMessage = message;
    _isInteractionStatusOpen = true;
    _interactionStatusTransitionInProgress = true;
  });

  _interactionStatusAnimationController.stop();
  _interactionStatusAnimationController.value = 0;
  await _interactionStatusAnimationController.forward();

  if (!mounted) return;
  if (generation != _interactionStatusGeneration) return;

  _safeSetState(() {
    _interactionStatusTransitionInProgress = false;
  });

  if (_interactionStatusDismissRequested) {
    _interactionStatusDismissRequested = false;
    await _hideInteractionStatusMessage();
  }
}

Future<void> _hideInteractionStatusMessage() async {
  if (!_isInteractionStatusOpen) return;
  if (_interactionStatusTransitionInProgress) {
    _interactionStatusDismissRequested = true;
    return;
  }

  final generation = ++_interactionStatusGeneration;

  _safeSetState(() {
    _interactionStatusTransitionInProgress = true;
  });

  await _interactionStatusAnimationController.reverse();

  if (!mounted) return;
  if (generation != _interactionStatusGeneration) return;

  final nextMessage = _interactionStatusQueue.isEmpty
      ? null
      : _interactionStatusQueue.removeAt(0);

  _safeSetState(() {
    _interactionStatusMessage = null;
    _isInteractionStatusOpen = false;
    _interactionStatusTransitionInProgress = false;
    _interactionStatusDismissRequested = false;
  });

  if (nextMessage == null) return;
  if (_hasBlockingYardModalOpen()) {
    _enqueueInteractionStatusMessage(nextMessage);
    return;
  }

  await Future<void>.delayed(const Duration(milliseconds: 50));
  if (!mounted) return;
  await _showInteractionStatusMessage(nextMessage);
}

Widget _buildInteractionStatusMessageOverlay() {
  if (!_isInteractionStatusOpen && !_interactionStatusTransitionInProgress) {
    return const SizedBox.shrink();
  }
  final message = _interactionStatusMessage?.trim() ?? '';
  if (message.isEmpty) return const SizedBox.shrink();

  final panel = ClipRRect(
    borderRadius: BorderRadius.circular(20),
    child: BackdropFilter(
      filter: ui.ImageFilter.blur(sigmaX: 10, sigmaY: 10),
      child: DecoratedBox(
        decoration: BoxDecoration(
          color: Colors.black.withValues(alpha: 0.6),
          borderRadius: BorderRadius.circular(20),
        ),
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
          child: Align(
            alignment: Alignment.centerLeft,
            child: Text(
              message,
              textAlign: TextAlign.left,
              maxLines: 2,
              overflow: TextOverflow.ellipsis,
              style: const TextStyle(
                fontFamily: 'Pretendard',
                fontSize: 14,
                fontWeight: FontWeight.w600,
                color: Color(0xFFFFFFFF),
                height: 1.35,
              ),
            ),
          ),
        ),
      ),
    ),
  );

  return Positioned.fill(
    child: Stack(
      fit: StackFit.expand,
      children: [
        Positioned.fill(
          child: GestureDetector(
            behavior: HitTestBehavior.opaque,
            onTap: () {
              unawaited(_hideInteractionStatusMessage());
            },
            child: const SizedBox.expand(),
          ),
        ),
        Positioned(
          left: _kInteractionStatusLeft,
          top: _kInteractionStatusTop,
          width: _kInteractionStatusWidth,
          height: _kInteractionStatusHeight,
          child: FadeTransition(
            opacity: _interactionStatusOpacity,
            child: ScaleTransition(
              scale: _interactionStatusScale,
              alignment: Alignment.center,
              child: Semantics(
                liveRegion: true,
                label: message,
                child: panel,
              ),
            ),
          ),
        ),
      ],
    ),
  );
}

